    function buildGraveyard(cx, cz, seed) {
      const rnd = mulberry32(seed);
      const gy = sampleHeight(cx, cz) - 0.04;
      const lm = {
        kind: 'graveyard', x: cx, z: cz, gy, hp: GRAVEYARD_MAX_HP, maxHp: GRAVEYARD_MAX_HP, alive: true,
        mesh: null, colliders: [], debrisColor: 0x8a8a84, rubbleRadius: 3.0
      };
      const parts = [];
      const stone = new THREE.MeshStandardMaterial({ color: 0x8a8a84 });
      const stoneOld = new THREE.MeshStandardMaterial({ color: 0x6e6e66 });
      const deadwood = new THREE.MeshStandardMaterial({ color: 0x4a3a2c });
      const graveStones = [];
      for (let i = 0; i < 9; i++) {
        const gx = ((i % 3) - 1) * 2.6 + (rnd() - 0.5) * 0.9;
        const gz = (Math.floor(i / 3) - 1) * 2.4 + (rnd() - 0.5) * 0.9;
        // Each stone stands on its own ground.
        const dy = sampleHeight(cx + gx, cz + gz) - gy - 0.06;
        const h = 0.55 + rnd() * 0.5;
        const tilt = (rnd() - 0.5) * 0.5;
        rnd(); // keep the established seeded plot layout stable
        graveStones.push({ gx, gz, dy, h, tilt, angle: rnd() * 0.4 });
        lm.colliders.push(addSolid(cx + gx, cz + gz, 0.34, gy + dy, gy + dy + h + 0.2, lm));
      }
      // Bare dead tree watching over the plots.
      const treeDy = sampleHeight(cx - 3.4, cz - 2.8) - gy - 0.08;
      const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.28, 3.4, 7), deadwood);
      trunk.position.set(-3.4, treeDy + 1.7, -2.8);
      trunk.rotation.z = 0.12;
      parts.push(trunk);
      for (let i = 0; i < 4; i++) {
        const a = rnd() * Math.PI * 2;
        poiBox(parts, deadwood, 0.1, 1.3, 0.1, -3.4 + Math.cos(a) * 0.6, treeDy + 3.1 + rnd() * 0.5, -2.8 + Math.sin(a) * 0.6, 0, Math.cos(a) * 1.0, Math.sin(a) * 0.8);
      }
      lm.colliders.push(addSolid(cx - 3.4, cz - 2.8, 0.4, gy + treeDy, gy + treeDy + 3.4, lm));

      const details = appendLandmarkDetails(parts, 'graveyard', cx, cz, gy, 0, { stones: graveStones });
      details.register(lm);

      const mesh = mergeParts(parts, poiMat, { castShadow: true, receiveShadow: true });
      mesh.position.set(cx, gy, cz);
      scene.add(mesh);
      lm.mesh = mesh;

      mesh.userData.landmarkTheme = details.theme;

      landmarks.push(lm);
      return lm;
    }

