// Coldwater, by the old cemetery: the church's shell, three footings and a chimney.
if (POI.graveyard) {
  const gx = POI.graveyard.x, gz = POI.graveyard.z;
  const ch = historyFreeSpot(gx, gz, 11, 20, 4.5, 1.1);
  if (ch) put(History.buildChurchShell(THREE, rnd), ch.x, ch.z, Math.atan2(gx - ch.x, gz - ch.z), 6.5);
  for (let k = 0; k < 3; k++) {
    const f = historyFreeSpot(gx, gz, 18 + k * 4, 34, 3.6, 2.4 + k * 1.7);
    if (f) put(History.buildRuinedFoundation(THREE, rnd, { w: 5 + rnd() * 2, d: 4 + rnd() * 1.5, door: true, variant: k }), f.x, f.z, rnd() * Math.PI * 2, 3.8);
  }
  const cm = historyFreeSpot(gx, gz, 24, 38, 1.4, 4.0);
  if (cm) put(History.buildChimney(THREE, rnd), cm.x, cm.z, rnd() * 6, 1.0);
  // The cemetery itself: two coffins' iron bands showing where the ground slumped, and the one opened from below.
  // The older graves out past its fence and its clutter (its own signs and posts are not solids), clear of the gate.
  for (let k = 0; k < 2; k++) { const b = historyFreeSpot(gx, gz, 9.5, 13, 1.0, 0.9 + k * 0.5); if (b) put(History.buildIronBandedGrave(THREE, rnd), b.x, b.z, Math.atan2(b.x - gx, b.z - gz), 0.8, -0.04); }
  const o = historyFreeSpot(gx, gz, 10, 14, 1.3, 2.2);
  if (o) { const og = put(History.buildOpenGrave(THREE, rnd), o.x, o.z, 0.1, 1.2, -0.02); spot('graveyard', og.position.x, og.position.z, 2.8); }
}
